def backfill_votes(apps, schema_editor):
    """Existing quick-poll votes: unique_key keeps "one pick per candidate per voter"; nepal_date for daily counts."""
    from zoneinfo import ZoneInfo
    tz = ZoneInfo('Asia/Kathmandu')
    Vote = apps.get_model('voting', 'Vote')
    for v in Vote.objects.all().only('id', 'voter_identifier', 'candidate_id', 'voted_at').iterator():
        Vote.objects.filter(pk=v.pk).update(
            unique_key=f'{v.voter_identifier}:{v.candidate_id}', nepal_date=v.voted_at.astimezone(tz).date(), method='',
        )


